from math import gcd

def divisors(n, a):
	d = {}
	bad = []
	for i in range(n):
		c = a[i]
		if int(c ** 0.25 + 0.0001) ** 4 == c:
			p = int(c ** 0.25 + 0.0001)
			if p not in d:
				d[p] = 4
			else:
				d[p] += 4
		elif int(c ** (1 / 3) + 0.0001) ** 3 == c:
			p = int(c ** (1 / 3) + 0.0001)
			if p not in d:
				d[p] = 3
			else:
				d[p] += 3
		elif int(c ** 0.5 + 0.001) ** 2 == c:
			p = int(c ** 0.5 + 0.0001)
			if p not in d:
				d[p] = 2
			else:
				d[p] += 2
		else:
			bad.append(c)
	skipped = {}
	for i in range(len(bad)):
		for j in range(len(a)):
			g = gcd(bad[i], a[j])
			if bad[i] == a[j] or g == 1:
				continue
			else:
				if g not in d:
					d[g] = 1
				else:
					d[g] += 1
				if bad[i] // g not in d:
					d[bad[i] // g] = 1
				else:
					d[bad[i] // g] += 1
				break
		else:
			if bad[i] not in skipped:
				skipped[bad[i]] = 1
			else:
				skipped[bad[i]] += 1
	ans = 1
	MOD = 998244353
	for i in d:
		ans = ans * (d[i] + 1) % MOD
	for i in skipped:
		ans = ans * (skipped[i] + 1) ** 2 % MOD
	return ans
n = int(input())
a = [int(input()) for i in range(n)]
result = divisors(n, a)
print(result)
